3	 * sc4sap PreToolUse hook — Evidence guard.
4	 *
5	 * Denies agent writes to the evidence ledger (`.sc4sap/evidence/`) and to
6	 * `receipt.json` files, so the receipt can only come from build-receipt.mjs; and to the
7	 * program-test run files the capture hook / pt.mjs write (state, captured rows and source,
8	 * generated harness, pt-receipt).
9	 *
10	 *   Write / Edit / MultiEdit / NotebookEdit → deny when the target path is protected.
11	 *   Bash / PowerShell → deny when the command names a protected path, unless the
12	 *   command only runs build-receipt.mjs or program-test/pt.mjs. Reading these files goes through Read.
13	 *
14	 * Limit: a determined agent could still write a script elsewhere and run it.
15	 * The guard stops the easy paths; the user's check in the TCode stays the final gate.
16	 * Fails open on parse errors.
17	 */
18	
19	import { homedir } from 'node:os';
20	import { dirname, join, resolve } from 'node:path';
21	import { fileURLToPath } from 'node:url';
22	import { readStdin } from '../lib/stdin.mjs';
23	
24	// The one pt.mjs allowed to write program-test run files: this plugin's own copy, resolved from
25	// this file's location — a copy written elsewhere does not pass.
26	const GUARD_DIR = dirname(fileURLToPath(import.meta.url));
27	const PT_PATH = resolve(GUARD_DIR, '..', 'program-test', 'pt.mjs');
28	// The allow-listed md-to-html.mjs / build-receipt.mjs: this plugin's own copies, resolved the same way.
29	const MD_PATH = resolve(GUARD_DIR, '..', 'spec', 'md-to-html.mjs');
30	const BR_PATH = resolve(GUARD_DIR, 'build-receipt.mjs');
31	const normPath = (p) => resolve(p).replace(/\\/g, '/').toLowerCase();
32	const WIN = process.platform === 'win32';
33	/** A Git Bash drive path (/c/Users/…) as Windows reads it (C:/Users/…); other paths unchanged. */
34	const nativePath = (p) => (WIN ? String(p).replace(/^\/([a-zA-Z])(?=\/|$)/, '$1:') : String(p));
35	/** True when `script`, resolved against `base`, is exactly `target` (case-insensitive on Windows). */
36	const isPluginScript = (script, base, target) => {
37	  const key = (p) => { const r = resolve(p).replace(/\\/g, '/'); return WIN ? r.toLowerCase() : r; };
38	  return key(resolve(nativePath(base || process.cwd()), nativePath(script))) === key(target);
39	};
40	
41	/** True when the command only runs the plugin's own pt.mjs (absolute, or relative to the cwd) with plain arguments. */
42	export function onlyPluginPt(cmd, cwd) {
43	  const m = String(cmd).match(/^\s*node\s+(?:"([^"]+)"|(\S+))((?:\s+[\w\-,.:\\/"]+)*)\s*$/);
44	  if (!m) return false;
45	  const script = m[1] ?? m[2];
46	  if (!/pt\.mjs$/i.test(script)) return false;
47	  return normPath(resolve(cwd || process.cwd(), script)) === normPath(PT_PATH);
48	}
49	
50	const PROTECTED_BASE = /\.sc4sap[\\/]+(?:evidence(?:[\\/]|\b)|program[\\/]+[^\\/\s"']+[\\/]+receipt\.json|(?:work[\\/]+[^\\/\s"']+[\\/]+)?program[\\/]+[^\\/\s"']+[\\/]+test[\\/]+[^\\/\s"']+[\\/]+(?:state\.json|capture\.jsonl|fingerprints\.json|pt-receipt\.json|rows(?:[\\/]|\b)|src(?:[\\/]|\b)|ddic(?:[\\/]|\b)|harness(?:[\\/]|\b))|program-test[\\/]+active\.json)/i;
51	// A program-test run under any base folder (`pt.mjs init --base`, e.g. a web run's own output folder):
52	// program/<PROG>/test/<yyyymmdd-hhmmss>/<script- or hook-written file>.
53	const PROTECTED_RUN = /(?:^|[\\/])program[\\/]+[^\\/\s"']+[\\/]+test[\\/]+\d{8}-\d{6}[\\/]+(?:state\.json|capture\.jsonl|fingerprints\.json|pt-receipt\.json|rows(?:[\\/]|\b)|src(?:[\\/]|\b)|ddic(?:[\\/]|\b)|harness(?:[\\/]|\b))/i;
54	const PROTECTED = { test: (s) => PROTECTED_BASE.test(s) || PROTECTED_RUN.test(s) };
55	const FILE_TOOLS = new Set(['Write', 'Edit', 'MultiEdit', 'NotebookEdit']);
56	const SHELL_TOOLS = new Set(['Bash', 'PowerShell']);
57	
58	// ── the MCP server's masking key (profiles/<alias>/mask.key) ─────────────────
59	// Tokens of masked test-data reads are HMAC under this key; a model that could read it could
60	// test guessed values against the tokens. Defense in depth — the same OS user's shell can
61	// always reach a file the MCP server reads (residual risk accepted by the user for local,
62	// single-user CLI use). Denied:
63	//   - any tool input naming mask.key, also after removing quotes, backslashes, [ ] , + , ` , ^;
64	//   - Grep over a folder that holds the profile folders or sits inside one;
65	//   - shell commands naming the profiles folder (cd / pushd / Set-Location into it included),
66	//     unless they only move / delete, or read exactly <profile>/sap.env or config.json;
67	//   - shell commands reading the sc4sap home with a wildcard or recursively;
68	//   - links (ln / mklink / SymbolicLink / Junction) in commands naming the sc4sap home; a shell
69	//     whose cwd is inside the home climbing out of it;
70	//   - interpreter one-liners (node -e, python -c, powershell -c, bash -c, …) and encoded
71	//     PowerShell that reference the sc4sap home or the user's home folder.
72	// Allowed despite the above: only the two whole commands of allowListedCommand (below).
73	const MASK_KEY = /mask\.key/i;
74	const WIDE_READ = /[*?]|(?:^|\s)-[a-zA-Z]*[rR][a-zA-Z]*\b|-Recurse\b|\s\/s\b|\btar\b|\bzip\b|\brobocopy\b|\bxcopy\b/;
75	const MOVE_ONLY = /^\s*(?:rm|mv|mkdir|rmdir|Remove-Item|Move-Item|New-Item)\b/i;
76	const CHAINED = /;|&&|\|\||\||\$\(|`|\n|\r/;
77	const CD_LIKE = /(?:^|[;&|\s])(?:cd|pushd|Set-Location|sl|chdir)\s/i;
78	const SC4SAP_HOME_REF = /\.sc4sap(?:\/|\b)|SC4SAP_HOME_DIR/i;
79	const PROFILES_REF = /(?:\.sc4sap|SC4SAP_HOME_DIR)[^\s"']*?\/+profiles\b/i;
80	const EXACT_PROFILE_FILE = /(?:\.sc4sap|SC4SAP_HOME_DIR)[^\s"']*?\/+profiles\/+[\w.-]+\/+(?:sap\.env|config\.json)(?![\w.])/gi;
81	const INTERPRETER = /\b(?:node|nodejs|deno|bun)(?:\.exe)?\b[^|;&]*\s(?:-e|--eval|-p|--print|eval)\b|\bpython[0-9.]*(?:\.exe)?\b[^|;&]*\s-c\b|\b(?:perl|ruby|php)(?:\.exe)?\b[^|;&]*\s-[er]\b|\b(?:powershell|pwsh)(?:\.exe)?\b[^|;&]*\s-(?:c|command|e|ec|encodedcommand)\b|\b(?:bash|sh|zsh|dash)(?:\.exe)?\b[^|;&]*\s-c\b|\bcmd(?:\.exe)?\b[^|;&]*\s\/[ck]\b|\b(?:Invoke-Expression|iex)\b/i;
82	const HOME_REF = /\.sc4sap|sc4sap_home|homedir|USERPROFILE|\$HOME\b|\$env:HOME\b|%HOMEPATH%|~\//i;
83	// Decoding inside a command hides the path it reads (`cat $(echo <base64> | base64 -d)`).
84	const DECODE = /\bbase64\b[^|;&]*\s(?:-d|-D|--decode)\b|\bcertutil(?:\.exe)?\b[^|;&]*\s[-/]decode(?:hex)?\b|FromBase64String|\bopenssl\b[^|;&]*\b(?:base64|enc)\b[^|;&]*\s-d\b|\bxxd\b[^|;&]*\s-r\b/i;
85	const ENCODED_PS =/\b(?:powershell|pwsh)(?:\.exe)?\b[^|;&]*\s-(?:e|ec|encodedcommand)\b/i;
86	const GLOB_CHARS = /[*?[\]]/;
87	const DOT_DOT = /(?:^|[\\/\s"'=])\.\.(?:[\\/\s"']|$)/;
88	const PROFILES_WORD = /profiles/i;
89	const LINK = /(?:^|[\s;&|(])(?:ln|link|mklink|fsutil)(?:\.exe)?\s|SymbolicLink|Junction|HardLink|CreateSymbolicLink|symlink/i;
90	// a shell whose cwd is inside the home must not walk up from it (pwd | dirname, (Get-Item .).Parent, ~+)
91	const CLIMB = /\b(?:pwd|dirname|Split-Path|Get-Location|Get-Item|Resolve-Path|realpath|readlink|find|xargs)\b|\.Parent\b|\$PWD\b|~\+|\bgl\b|\bgi\b/i;
92	
93	// ── allow-list: two plugin scripts on a program's state folder ──────────────
94	// The ONE exception to the home checks below. The WHOLE command (trimmed) must be, after an
95	// optional leading `cd <dir> && ` (<dir> without .sc4sap):
96	//   node <path>/scripts/spec/md-to-html.mjs <path>/.sc4sap/program/<NAME>/<file>.md
97	//   node <path>/scripts/evidence/build-receipt.mjs <NAME> [--also <list>] [--unit-test required]
98	// <path> = [A-Za-z0-9_:/.-], optionally in double quotes, no `..` segment, no `profiles`; no shell
99	// syntax anywhere (; | & $ ` { } \ * ? [ < > or a line break). The script, resolved against the
100	// hook's cwd and the optional `cd <dir>`, must be this plugin's own copy (MD_PATH / BR_PATH) — a
101	// same-named script elsewhere does not pass. No token is ever cut out of a command: anything else
102	// naming the sc4sap home goes through the checks unchanged.
103	const AL_TOK = String.raw`("[A-Za-z0-9_:/.-]+"|[A-Za-z0-9_:/.-]+)`;
104	const AL_CD = new RegExp(String.raw`^cd[ \t]+${AL_TOK}[ \t]+&&[ \t]+`);
105	const AL_MD = new RegExp(String.raw`^node[ \t]+${AL_TOK}[ \t]+${AL_TOK}$`);
106	const AL_BR = new RegExp(String.raw`^node[ \t]+${AL_TOK}[ \t]+[A-Z0-9_/]{1,40}(?:[ \t]+--also[ \t]+[A-Z0-9_/,]{1,400})?(?:[ \t]+--unit-test[ \t]+required)?$`);
107	const AL_FORBIDDEN = /[;|&$`{}\\*?[\]<>\r\n]/;
108	const MD_TARGET = /^(?:([A-Za-z0-9_:/.-]*)\/)?\.sc4sap\/program\/[A-Z0-9_/]{1,40}\/[A-Za-z0-9_.-]+\.md$/;
109	const unq = (t) => t.replace(/^"(.*)"$/, '$1');
110	const plainPath = (p) => !p.split('/').includes('..') && !PROFILES_WORD.test(p);
111	const scriptPath = (t, base, target) => { const p = unq(t); return plainPath(p) && !/\.sc4sap/i.test(p) && isPluginScript(p, base, target); };
112	/** True when the whole command is one of the two allow-listed plugin script calls. */
113	export function allowListedCommand(command, cwd) {
114	  let c = String(command).trim();
115	  let base = cwd || process.cwd();
116	  const cd = c.match(AL_CD);
117	  if (cd) {
118	    const dir = unq(cd[1]);
119	    const homeN = normPath(sc4sapHome());
120	    base = resolve(nativePath(base), nativePath(dir));
121	    if (!plainPath(dir) || /\.sc4sap/i.test(dir) || dir.toLowerCase().includes(homeN) || within(base, sc4sapHome()) || within(resolve(cwd || process.cwd(), dir), sc4sapHome())) return false;
122	    c = c.slice(cd[0].length);
123	  }
124	  if (AL_FORBIDDEN.test(c)) return false;
125	  const md = c.match(AL_MD);
126	  if (md && scriptPath(md[1], base, MD_PATH)) {
127	    const target = unq(md[2]).match(MD_TARGET);
128	    return !!target && plainPath(unq(md[2])) && !/\.sc4sap/i.test(target[1] || '');
129	  }
130	  const br = c.match(AL_BR);
131	  return !!br && scriptPath(br[1], base, BR_PATH);
132	}
133	const sc4sapHome = () => resolve(process.env.SC4SAP_HOME_DIR || join(homedir(), '.sc4sap'));
134	const within = (child, parent) => {
135	  const c = normPath(child);
136	  const p = normPath(parent);
137	  return c === p || c.startsWith(`${p}/`);
138	};
139	/** Text without the characters a shell drops or joins: quotes, [ ], +, `, ^ (backslashes kept as /). */
140	const flatten = (s) => String(s).replace(/["'`^[\]+]/g, '').replace(/\\/g, '/');
141	/** Same, backslashes removed (a shell reads mas\k.key as mask.key). */
142	const flattenNoBackslash = (s) => String(s).replace(/["'`^[\]+\\]/g, '');
143	
144	/** Deny reason when a call would read the MCP server's masking key, else null. */
145	export function maskKeyRefusal(payload) {
146	  const tool = payload?.tool_name;
147	  const input = payload?.tool_input || {};
148	  const texts = ['file_path', 'notebook_path', 'path', 'pattern', 'glob', 'command'].map((k) => input[k]).filter((v) => typeof v === 'string');
149	  const reason = 'the MCP masking key (profiles/<alias>/mask.key) is never read by the model';
150	  if (texts.some((t) => MASK_KEY.test(t) || MASK_KEY.test(flatten(t)) || MASK_KEY.test(flattenNoBackslash(t)))) return reason;
151	  if (tool === 'Grep') {
152	    const root = resolve(payload?.cwd || process.cwd(), typeof input.path === 'string' && input.path ? input.path : '.');
153	    const profiles = join(sc4sapHome(), 'profiles');
154	    // a search root at or above the profile folders, or inside one of them
155	    if (within(profiles, root) || within(root, profiles)) return `${reason}; grep a single file such as config.json instead`;
156	  }
157	  if (SHELL_TOOLS.has(tool)) {
158	    const raw = String(input.command || '');
159	    const full = flatten(raw);
160	    const fullNb = flattenNoBackslash(raw);
161	    // the shell already sits in a profile folder (its working directory persists)
162	    if (payload?.cwd && within(resolve(payload.cwd), join(sc4sapHome(), 'profiles'))) return `${reason}; leave the profile folder first`;
163	    // a shell inside the sc4sap home (e.g. a program folder there) must not climb, name profiles,
164	    // build a path from variables / braces / substitutions, or make links
165	    if (payload?.cwd && within(resolve(payload.cwd), sc4sapHome())
166	      && (DOT_DOT.test(full) || DOT_DOT.test(fullNb) || PROFILES_WORD.test(full) || PROFILES_WORD.test(fullNb) || /[$`{]/.test(raw) || LINK.test(full) || LINK.test(fullNb) || CLIMB.test(full)))
167	      return `${reason}; leave the sc4sap folder first`;
168	    // the one exception: the whole command is an allow-listed plugin script call
169	    if (allowListedCommand(raw, payload?.cwd)) return null;
170	    // the sc4sap home as written (.sc4sap / SC4SAP_HOME_DIR) or as its resolved path
171	    const homeN = normPath(sc4sapHome());
172	    const namesHome = (s) => SC4SAP_HOME_REF.test(s) || s.toLowerCase().includes(homeN);
173	    const cmd = full;
174	    if ((namesHome(full) || namesHome(fullNb)) && (LINK.test(full) || LINK.test(fullNb))) return `${reason}; no links to or inside the sc4sap folder`;
175	    const lower = cmd.toLowerCase();
176	    const namesProfiles = (s) => PROFILES_REF.test(s) || s.toLowerCase().includes(`${homeN}/profiles`);
177	    const exactFiles = new RegExp(`${homeN.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}/profiles/+[\\w.-]+/+(?:sap\\.env|config\\.json)(?![\\w.])`, 'gi');
178	    if (ENCODED_PS.test(raw)) return `${reason}; encoded PowerShell cannot be checked`;
179	    if (DECODE.test(raw) || DECODE.test(cmd)) return `${reason}; a decoded command or path cannot be checked — write it out in plain text`;
180	    if (INTERPRETER.test(cmd) && (HOME_REF.test(cmd) || lower.includes(homeN))) return `${reason}; no interpreter one-liner on the sc4sap / home folder`;
181	    if (namesProfiles(cmd)) {
182	      const moveOnly = MOVE_ONLY.test(cmd) && !CHAINED.test(raw) && !CD_LIKE.test(cmd);
183	      const rest = cmd.replace(EXACT_PROFILE_FILE, '').replace(exactFiles, '');
184	      const exactFilesOnly = !namesProfiles(rest) && !CHAINED.test(raw) && !CD_LIKE.test(cmd) && !WIDE_READ.test(cmd);
185	      if (!moveOnly && !exactFilesOnly) return `${reason}; name the one file you need (sap.env / config.json)`;
186	    } else if ((namesHome(cmd) || namesHome(fullNb)) && (PROFILES_WORD.test(cmd) || PROFILES_WORD.test(fullNb)) && !(MOVE_ONLY.test(cmd) && !CHAINED.test(raw))) {
187	      // the home and `profiles` split apart, e.g. D=~/.sc4sap; cat $D/profiles/S4-DEV/x
188	      return `${reason}; name the one file you need (sap.env / config.json)`;
189	    }
190	    if (CD_LIKE.test(cmd) && namesHome(cmd)) return `${reason}; do not change into the sc4sap folder`;
191	    if (namesHome(cmd) && (WIDE_READ.test(cmd) || GLOB_CHARS.test(raw)) && !MOVE_ONLY.test(cmd)) return `${reason}; name the one file you need (sap.env / config.json)`;
192	  }
193	  return null;
194	}
195	
196	export function decide(payload) {
197	  const tool = payload?.tool_name;
198	  const input = payload?.tool_input || {};
199	  const keyRefusal = maskKeyRefusal(payload);
200	  if (keyRefusal) return keyRefusal;
201	  if (FILE_TOOLS.has(tool)) {
202	    const p = String(input.file_path || input.notebook_path || '');
203	    return PROTECTED.test(p) ? `${p} is written only by the sc4sap evidence hook / build-receipt.mjs` : null;
204	  }
205	  if (SHELL_TOOLS.has(tool)) {
206	    const cmd = String(input.command || '');
207	    if (!PROTECTED.test(cmd)) return null;
208	    // the plugin's own build-receipt.mjs (resolved against the cwd, as pt.mjs) with plain arguments
209	    const b = cmd.match(/^\s*node\s+("[^"]*build-receipt\.mjs"|\S*build-receipt\.mjs)(\s+[\w\-,.:\\/"]+)*\s*$/);
210	    const onlyBuilder = !!b && isPluginScript(unq(b[1]), payload?.cwd, BR_PATH);
211	    return onlyBuilder || onlyPluginPt(cmd, payload?.cwd) ? null : 'evidence ledger, receipt.json and program-test run files are protected; use the Read tool to read them, build-receipt.mjs / the plugin\'s program-test/pt.mjs to write them';
212	  }
213	  return null;
214	}
215	
216	async function main() {
217	  let reason = null;
218	  if (process.env.DISABLE_SC4SAP !== '1') {
219	    try {
220	      reason = decide(JSON.parse(await readStdin()));
221	    } catch {
222	      reason = null;
223	    }
224	  }
225	  if (!reason) {
226	    console.log(JSON.stringify({ continue: true, suppressOutput: true }));
227	    return;
228	  }
229	  console.log(
230	    JSON.stringify({
231	      continue: true,
232	      hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: `sc4sap evidence guard: ${reason}` },
233	    })
234	  );
235	}
236	
237	if (process.argv[1]?.replace(/\\/g, '/').endsWith('scripts/evidence/guard.mjs')) main();
238

