// Mobile checks on the local web app with real device emulation:
//   iPhone 13 on WebKit (Safari's engine) and Pixel 7 on Chromium,
//   touch events on, coarse pointer, mobile viewport.
//   node check.mjs /path [/path2 …] [--device iphone|android|both] [--shots]
// Per page: sideways scroll, touch targets < 44px, inputs < 16px, console errors.
// Drawer check (--drawer): open menu → close → open → touch-drag the menu list.
import { existsSync, mkdirSync } from "node:fs";
import { chromium, devices, webkit } from "playwright";

const args = process.argv.slice(2);
const paths = args.filter((a) => a.startsWith("/"));
const which = (args[args.indexOf("--device") + 1] || "both").toLowerCase();
const shots = args.includes("--shots");
const drawer = args.includes("--drawer");
const base = process.env.QA_BASE || "http://localhost:3000";
const state = new URL("./storage-state.json", import.meta.url);
if (!existsSync(state)) {
  console.error("No saved session: run `node login.mjs` and sign in first.");
  process.exit(2);
}
const targets = [
  ...(which !== "android" ? [{ name: "iPhone 13 (WebKit)", engine: webkit, device: devices["iPhone 13"] }] : []),
  ...(which !== "iphone" ? [{ name: "Pixel 7 (Chromium)", engine: chromium, device: devices["Pixel 7"] }] : []),
];
if (shots) mkdirSync(new URL("./shots/", import.meta.url), { recursive: true });

for (const t of targets) {
  const browser = await t.engine.launch();
  const context = await browser.newContext({ ...t.device, storageState: state.pathname.replace(/^\/([A-Z]:)/, "$1") });
  for (const path of paths) {
