// Renders the web review page (bc4852d) with questions + "not read" in ko and en for a 390px check.
import { writeFileSync } from "node:fs";
import { reviewHtml } from "C:/Users/pssps/Documents/Projects/sc4sap_project/sc4sap_web/web/src/lib/review-doc";

const out = process.argv[2];
for (const language of ["ko", "en"]) {
  const html = reviewHtml({
    object: "ZMMR_DEMO_REPORT_WITH_A_LONG_NAME",
    type: "PROG",
    language,
    title: language === "ko" ? "코드 리뷰" : "Code review",
    summary: language === "ko" ? "전반적으로 안정적이지만 확인할 업무 질문이 3개 있어요." : "Stable overall, with 3 business questions to confirm.",
    score: 78,
    topFix: "SELECT in LOOP → FOR ALL ENTRIES",
    findings: [
      { id: 1, severity: "high", location: "ZMMR_DEMO_REPORT_F01 line 120-135", title: "SELECT inside LOOP", detail: "Each row reads EKPO again.", fix: "Read once with FOR ALL ENTRIES." } as never,
      { id: 2, severity: "medium", location: "ZMMR_DEMO_REPORT_TOP", title: "Hard-coded plant", detail: "WERKS = '1000' is fixed.", fix: "Use a selection parameter." } as never,
    ],
    questions: [
      { id: "Q1", location: "ZMMR_DEMO_REPORT_F01:142", ask: language === "ko" ? "삭제 표시(LOEKZ)된 PO 품목도 목록에 보여야 하나요? 지금은 함께 나와요." : "Should PO items flagged for deletion (LOEKZ) be listed? They are listed today.", ifNot: "WHERE loekz = space" },
      { id: "Q2", location: "ZMMR_DEMO_REPORT_F02:88", ask: language === "ko" ? "입고 수량이 0인 품목은 제외하는 게 맞나요?" : "Is it right to drop items with zero GR quantity?", ifNot: "DELETE lt_items WHERE wemng = 0. → remove" },
      { id: "Q3", location: "ZCL_MMR_DEMO_VERY_LONG_CLASS_NAME_HANDLER=>BUILD_OUTPUT_TABLE_FOR_ALV", ask: language === "ko" ? "통화가 다른 품목을 한 줄로 합산해도 되나요?" : "May items in different currencies be summed into one line?", ifNot: "COLLECT by WAERS" },
    ],
    notRead: language === "ko" ? "호출하는 프로그램(SUBMIT 2곳), 실제 데이터, 사용자 권한" : "Calling programs (2 SUBMITs), runtime data, user authorizations",
    next: [language === "ko" ? "Q1 답을 반영해 줘" : "Apply the answer to Q1"],
    generated: "2026-11-23",
  });
  writeFileSync(`${out}/review-${language}.html`, html);
}
console.log("ok");

