import { pathToFileURL } from "node:url";
import { createRequire } from "node:module";
const require = createRequire("C:/Users/pssps/Documents/Projects/sc4sap_project/tools/mobile-qa/package.json");
const { chromium, webkit, devices } = require("playwright");
const dir = process.argv[2];
const targets = [
  { name: "iPhone13-WebKit", engine: webkit, device: devices["iPhone 13"] },
  { name: "Pixel7-Chromium", engine: chromium, device: devices["Pixel 7"] },
];
for (const t of targets) {
  const browser = await t.engine.launch();
  const ctx = await browser.newContext({ ...t.device, viewport: { width: 390, height: 844 } });
  for (const lang of ["ko", "en"]) {
    const page = await ctx.newPage();
    const errors = [];
    page.on("pageerror", (e) => errors.push(String(e)));
    await page.goto(pathToFileURL(`${dir}/review-${lang}.html`).href);
    await page.waitForTimeout(400);
    const r = await page.evaluate(() => {
      const vw = document.documentElement.clientWidth;
      const sideways = document.documentElement.scrollWidth - vw;
      const wide = [];
      for (const el of document.querySelectorAll("body *")) {
        const b = el.getBoundingClientRect();
        if (b.width === 0) continue;
        // inside a horizontal scroller is fine
        let p = el.parentElement, scroller = false;
        while (p) { const s = getComputedStyle(p); if (/(auto|scroll)/.test(s.overflowX) && p.scrollWidth > p.clientWidth) { scroller = true; break; } p = p.parentElement; }
        if (!scroller && b.right > vw + 1) wide.push(`${el.tagName.toLowerCase()}.${String(el.className).slice(0, 30)} right=${Math.round(b.right)}`);
      }
      const q = document.body.innerText.match(/확인이 필요한 업무 질문|Business questions to confirm/) ? "questions shown" : "questions MISSING";
      const nr = document.body.innerText.match(/못 본 곳|Not read/) ? "not-read shown" : "not-read MISSING";
      const small = [...document.querySelectorAll("button, a[href]")].filter((e) => { const b = e.getBoundingClientRect(); return b.width > 0 && (b.width < 24 || b.height < 24); }).length;
      return { vw, sideways, wide: wide.slice(0, 8), wideCount: wide.length, q, nr, small };
    });
    await page.screenshot({ path: `${dir}/${t.name}-${lang}.png`, fullPage: true });
    console.log(`${t.name} ${lang}: vw=${r.vw} sideways=${r.sideways}px overflowing=${r.wideCount} ${r.q}, ${r.nr}, tiny targets=${r.small}, js errors=${errors.length}`);
    for (const w of r.wide) console.log(`   ${w}`);
    await page.close();
  }
  await browser.close();
}

